sp_widget.client_script:
api.controller = function($scope, $interval) {
  var c = this;

  // Track upload state per document
  c.uploadingDoc = null;
  c.uploadSuccess = null;
  c.uploadError = null;

  // File selection for a specific rejected document
  c.triggerFileSelect = function(doc) {
    // Reset messages
    c.uploadSuccess = null;
    c.uploadError = null;
    // Programmatically click the hidden file input for this doc
    var fileInput = document.getElementById('reupload-' + doc.sys_id);
    if (fileInput) {
      fileInput.click();
    }
  };

  // Handle file selection and upload
  c.handleFileChange = function(doc, files) {
    if (!files || files.length === 0) return;
    var file = files[0];

    // Validate file type
    var allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'image/jpg'];
    if (allowedTypes.indexOf(file.type) === -1) {
      c.uploadError = 'Invalid file type. Please upload a PDF or image file.';
      $scope.$apply();
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      c.uploadError = 'File too large. Maximum size is 10MB.';
      $scope.$apply();
      return;
    }

    c.uploadingDoc = doc.sys_id;
    $scope.$apply();

    // Read file as base64
    var reader = new FileReader();
    reader.onload = function(e) {
      var base64 = e.target.result.split(',')[1]; // Remove data:...;base64, prefix

      c.server.get({
        action: 'reupload_document',
        docSysId: doc.sys_id,
        fileName: file.name,
        fileType: file.type,
        base64: base64
      }).then(function(response) {
        c.uploadingDoc = null;
        if (response.data.reuploadResult === 'success') {
          c.uploadSuccess = response.data.reuploadMessage || 'Document re-uploaded successfully.';
          c.uploadError = null;
          // Refresh the entire data object
          c.data = response.data;
        } else {
          c.uploadError = response.data.reuploadMessage || 'Upload failed. Please try again.';
          c.uploadSuccess = null;
        }
      }, function() {
        c.uploadingDoc = null;
        c.uploadError = 'Network error. Please try again.';
      });
    };
    reader.onerror = function() {
      c.uploadingDoc = null;
      c.uploadError = 'Could not read file. Please try again.';
      $scope.$apply();
    };
    reader.readAsDataURL(file);
  };

  // Auto-refresh polling (keep existing)
  if (c.data && c.data.hasRecord) {
    var timer = $interval(function() {
      if (!c.uploadingDoc) { // Don't refresh during upload
        c.server.get({ action: 'refreshStatus' }).then(function(response) {
          if (!c.uploadingDoc) { // Double-check still not uploading
            c.data = response.data;
          }
        });
      }
    }, 20000);
    $scope.$on('$destroy', function() { $interval.cancel(timer); });
  }
};

sp_widget.css:
.gvft-status-container {
  background-color: #1e4587;
  color: #ffffff;
  min-height: 100vh;
  padding: 40px 60px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-sizing: border-box;
}

/* Header */
.status-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 25px;
  max-width: 950px;
}

.badge-case {
  background: #38bdf8;
  color: #0c4a6e;
  padding: 4px 10px;
  font-weight: 700;
  border-radius: 4px;
  font-size: 13px;
  display: inline-block;
  margin-bottom: 8px;
}

.applicant-name {
  font-size: 32px;
  font-weight: 600;
  margin: 0 0 6px 0;
  color: #ffffff;
}

.role-sub {
  color: #cbd5e1;
  font-size: 14px;
  margin: 0;
}

.bullet-sep {
  margin: 0 8px;
  color: #64748b;
}

.status-pill {
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.status-submitted { background-color: #0284c7; }
.status-under_review { background-color: #f59e0b; color: #1e293b; }
.status-pre_approved, .status-approved { background-color: #10b981; }

/* Progress Card & Percentage Indicator */
.progress-section-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  padding: 24px 30px 20px 30px;
  margin-bottom: 25px;
  max-width: 950px;
}

.progress-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.progress-title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
}

.percentage-badge {
  background: #38bdf8;
  color: #0c4a6e;
  font-weight: 700;
  font-size: 14px;
  padding: 4px 12px;
  border-radius: 12px;
}

.progress-bar-track {
  height: 10px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 5px;
  overflow: hidden;
  margin-bottom: 28px;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #0ea5e9);
  border-radius: 5px;
  transition: width 0.6s ease-in-out;
}

/* Stepper Nodes */
.stages-wrapper {
  display: flex;
  justify-content: space-between;
}

.stage-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 120px;
}

.node-circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #1e3a8a;
  border: 2px solid rgba(255, 255, 255, 0.4);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 8px;
}

.stage-node.active .node-circle {
  background: #38bdf8;
  color: #0c4a6e;
  border-color: #38bdf8;
}

.stage-node.current .node-circle {
  box-shadow: 0 0 0 5px rgba(56, 189, 248, 0.3);
}

.node-title {
  font-size: 12px;
  color: #94a3b8;
  text-align: center;
  font-weight: 500;
}

.stage-node.active .node-title {
  color: #ffffff;
  font-weight: 600;
}

/* Metrics Grid */
.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  max-width: 950px;
  margin-bottom: 25px;
}

.metric-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  padding: 18px;
}

.metric-card label {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  color: #94a3b8;
  margin-bottom: 6px;
}

.metric-value {
  font-size: 15px;
  font-weight: 600;
  color: #ffffff;
}

.text-success { color: #4ade80 !important; }
.text-warning { color: #fde047 !important; }
.code-font { font-family: monospace; font-size: 14px; }
.uppercase { text-transform: uppercase; }

/* Verification Table */
.checklist-card {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  padding: 20px;
  max-width: 950px;
}

.checklist-title {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 15px 0;
  color: #ffffff;
}

.custom-table {
  width: 100%;
  border-collapse: collapse;
}

.custom-table th {
  color: #94a3b8;
  font-size: 12px;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding: 8px 12px;
}

.custom-table td {
  padding: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  font-size: 13.5px;
}

.label-status {
  display: inline-block;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
}

.status-verified {
  background: rgba(74, 222, 128, 0.15);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.3);
}

/* Empty State */
.empty-state-card {
  text-align: center;
  padding: 80px 20px;
  max-width: 600px;
  margin: 0 auto;
}

.empty-icon {
  font-size: 54px;
  color: rgba(255, 255, 255, 0.3);
  margin-bottom: 16px;
}

.empty-title {
  font-size: 22px;
  margin-bottom: 8px;
}

.empty-desc {
  font-size: 14px;
  color: #cbd5e1;
  margin-bottom: 24px;
}

.btn-start {
  background: #38bdf8;
  color: #0c4a6e;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: 6px;
  text-decoration: none;
  display: inline-block;
}
/* Dynamic Document Status Colors */
.status-verified, 
.status-approved {
  background: rgba(74, 222, 128, 0.15);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.3);
}

.status-submitted, 
.status-pending, 
.status-in_review {
  background: rgba(253, 224, 71, 0.15);
  color: #fde047;
  border: 1px solid rgba(253, 224, 71, 0.3);
}

.status-uploaded {
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.3);
}

.status-rejected {
  background: rgba(248, 113, 113, 0.15);
  color: #f87171;
  border: 1px solid rgba(248, 113, 113, 0.3);
}

.review-notes-cell {
  font-size: 13px;
  color: #cbd5e1;
  font-style: italic;
}

/* ═══════════════════════════════════════════════════════
   Re-upload Action Styles
   ═══════════════════════════════════════════════════════ */
.reupload-btn {
  background: rgba(56, 189, 248, 0.2);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.4);
  padding: 5px 12px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}
.reupload-btn:hover {
  background: rgba(56, 189, 248, 0.35);
  color: #ffffff;
}
.reupload-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.upload-spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid rgba(56, 189, 248, 0.3);
  border-top-color: #38bdf8;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
  margin-right: 6px;
  vertical-align: middle;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
.action-cell {
  text-align: center;
  vertical-align: middle;
}
.upload-alert {
  padding: 10px 16px;
  border-radius: 6px;
  font-size: 13px;
  margin-bottom: 15px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.upload-alert-success {
  background: rgba(74, 222, 128, 0.15);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.3);
}
.upload-alert-error {
  background: rgba(248, 113, 113, 0.15);
  color: #f87171;
  border: 1px solid rgba(248, 113, 113, 0.3);
}
.file-input-hidden {
  display: none;
}
.action-check {
  color: rgba(255, 255, 255, 0.3);
  font-size: 14px;
}

sp_widget.script:
(function() {
  var caseTable = 'x_2023506_german_1_imm_case';
  var docTable  = 'x_2023506_german_1_case_doc';

  // ── DOC_NAME_MAP fallback for getDisplayValue quirks ──
  var DOC_NAME_MAP = {
      '1': 'Passport', '2': 'Passport Photo', '3': 'Job Contract', '4': 'Degree Certificate',
      'passport': 'Passport', 'Passport': 'Passport',
      'degree_certificate': 'Degree Certificate', 'Degree Certificate': 'Degree Certificate',
      'power_of_attorney': 'Power of Attorney', 'Power of Attorney': 'Power of Attorney',
      'job_contract': 'Job Contract', 'Job Contract': 'Job Contract',
      'Passport Photo': 'Passport Photo'
  };

  function resolveDocName(gr) {
      var display = gr.getDisplayValue('u_document_name');
      if (display && display.toString().trim() !== '' && !/^\d+$/.test(display.toString().trim())) {
          return display.toString().trim();
      }
      var raw = gr.getValue('u_document_name');
      if (raw && DOC_NAME_MAP[raw.toString().trim()]) {
          return DOC_NAME_MAP[raw.toString().trim()];
      }
      if (display && display.toString().trim()) {
          return display.toString().trim();
      }
      return 'Required Document';
  }

  // ── Handle document re-upload action ──
  if (input && input.action === 'reupload_document') {
      data.reuploadResult = 'pending';
      try {
          var docGr = new GlideRecord(docTable);
          if (docGr.get(input.docSysId)) {
              // Attach new file using GlideSysAttachment
              var sa = new GlideSysAttachment();
              var mimeType = input.fileType || 'application/pdf';
              sa.writeBase64(docGr, input.fileName, mimeType, input.base64);

              // Also attach to parent case
              var parentCaseSysId = docGr.getValue('u_case');
              if (parentCaseSysId) {
                  var caseGr = new GlideRecord(caseTable);
                  if (caseGr.get(parentCaseSysId)) {
                      sa.writeBase64(caseGr, input.fileName, mimeType, input.base64);
                  }
              }

              // Reset status and notes
              docGr.setValue('u_status', 'uploaded');
              docGr.setValue('u_review_notes', 'Re-uploaded by candidate. Pending caseworker re-verification.');
              docGr.update();

              data.reuploadResult = 'success';
              data.reuploadMessage = 'Document re-uploaded successfully. Pending re-verification.';
          } else {
              data.reuploadResult = 'error';
              data.reuploadMessage = 'Document record not found.';
          }
      } catch (ex) {
          data.reuploadResult = 'error';
          data.reuploadMessage = 'Upload failed: ' + ex.message;
      }
      // Don't return — fall through to reload the document matrix so the UI refreshes
  }

  // ── Case Lookup Chain ──
  var sysId = $sp.getParameter('sys_id');
  var grCase = new GlideRecord(caseTable);
  var found = false;

  // 1. Try by sys_id parameter
  if (sysId && grCase.get(sysId)) {
    found = true;
  }

  // 2. Try by logged-in user's email
  if (!found) {
    var userEmail = gs.getUser().getEmail();
    if (userEmail) {
      grCase = new GlideRecord(caseTable);
      grCase.addQuery('u_candidate_email', userEmail);
      grCase.orderByDesc('sys_created_on');
      grCase.setLimit(1);
      grCase.query();
      if (grCase.next()) {
        found = true;
      }
    }
  }

  // 3. Fallback: latest case
  if (!found) {
    grCase = new GlideRecord(caseTable);
    grCase.orderByDesc('sys_created_on');
    grCase.setLimit(1);
    grCase.query();
    if (grCase.next()) {
      found = true;
    }
  }

  if (found && grCase.isValidRecord()) {
    data.hasRecord = true;
    data.sysId = grCase.getUniqueValue();
    data.number = grCase.getValue('number');
    data.candidateName = grCase.getValue('u_candidate_name') || 'Applicant';
    data.city = grCase.getValue('u_target_city') || 'Germany';
    data.category = grCase.getValue('u_visa_category') || 'EU Blue Card';
    data.state = grCase.getDisplayValue('state') || 'Open';
    data.feeStatus = grCase.getValue('u_fee_status') || 'Pending';
    data.clearanceId = grCase.getValue('u_vorabzustimmung_id');
    data.passportNumber = grCase.getValue('u_passport_number');

    var stateVal = (grCase.getValue('state') || '').toString();
    data.stateKey = (data.state || '').toLowerCase().replace(/\s+/g, '_');

    // Percentage Calculation:
    // State 3 (Closed Complete) or 11 (Pre-Approved) -> 100%
    // State 10 (Government Review) -> 80%
    // State 9 (Document Check) -> 50%
    // State 1 (Open) / Default -> 25%
    if (stateVal === '11') {
      data.percent = 100;
      data.stageIndex = 4;
    } else if (stateVal === '10') {
      data.percent = 80;
      data.stageIndex = 3;
    } else if (stateVal === '9') {
      data.percent = 50;
      data.stageIndex = 2;
    } else {
      data.percent = 25;
      data.stageIndex = 1;
    }

    // ── Load Document Matrix ──
    data.documents = [];
    var grDoc = new GlideRecord(docTable);
    grDoc.addQuery('u_case', data.sysId);
    grDoc.orderBy('sys_created_on');
    grDoc.query();

    while (grDoc.next()) {
      var docStatusDisplay = grDoc.getDisplayValue('u_status') || 'Submitted';
      var docStatusRaw = (grDoc.getValue('u_status') || 'submitted').toLowerCase();
      var docLabel = resolveDocName(grDoc);

      data.documents.push({
        sys_id: grDoc.getUniqueValue(),
        name: docLabel.toString().trim() || 'Required Document',
        status: docStatusDisplay.toString(),
        statusKey: docStatusRaw.replace(/\s+/g, '_'),
        notes: (grDoc.getValue('u_review_notes') || 'Pending initial caseworker verification').toString()
      });
    }

  } else {
    data.hasRecord = false;
  }
})();
